const Modal = ({ isOpen, onClose, onConfirm, title, description, triggerRef }) => {
  const modalRef = useRef(null);

  useEffect(() => {
    if (isOpen) {
      // Prevent scrolling when modal is open
      document.body.style.overflow = 'hidden';

      // Focus management
      const focusableElements = modalRef.current.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      if (focusableElements.length > 0) {
        // Set timeout to ensure render is complete before focusing
        const timer = setTimeout(() => focusableElements[0].focus(), 10);

        const handleKeyDown = (e) => {
          if (e.key === 'Escape') onClose();
          if (e.key === 'Tab') {
            const first = focusableElements[0];
            const last = focusableElements[focusableElements.length - 1];
            if (e.shiftKey && document.activeElement === first) {
              last.focus();
              e.preventDefault();
            } else if (!e.shiftKey && document.activeElement === last) {
              first.focus();
              e.preventDefault();
            }
          }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
          clearTimeout(timer);
          window.removeEventListener('keydown', handleKeyDown);
          document.body.style.overflow = 'unset';
          if (triggerRef.current) triggerRef.current.focus();
        };
      }
    }
  }, [isOpen, onClose, triggerRef]);

  if (!isOpen) return null;

  return (
    <div 
      className="modal-overlay" 
      onClick={(e) => e.target === e.currentTarget && onClose()}
      aria-hidden={!isOpen}
    >
      <div 
        className="modal-content" 
        role="alertdialog" 
        aria-modal="true" 
        aria-labelledby="modal-title" 
        aria-describedby="modal-desc"
        ref={modalRef}
      >
        <h2 id="modal-title" className="modal-title">{title}</h2>
        <p id="modal-desc" className="modal-description">{description}</p>
        <div className="modal-actions">
          <button 
            type="button" 
            className="btn-secondary" 
            onClick={onClose}
          >
            Cancel
          </button>
          <button 
            type="button" 
            className="btn-danger" 
            onClick={onConfirm}
          >
            Confirm Delete
          </button>
        </div>
      </div>
    </div>
  );
};

const ImagePreviewPage = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleted, setIsDeleted] = useState(false);
  const triggerRef = useRef(null);

  const handleDeleteClick = () => {
    setIsModalOpen(true);
  };

  const handleConfirmDelete = () => {
    setIsDeleted(true);
    setIsModalOpen(false);
    // In a real app, you'd send a request to the server here
    console.log("Image deleted successfully");
  };

  if (isDeleted) {
    return (
      <main className="container">
        <h1>Image Deleted</h1>
        <p>The image has been removed from your library.</p>
        <button 
          className="btn-secondary" 
          onClick={() => setIsDeleted(false)}
          style={{marginTop: '20px'}}
        >
          Restore (Demo Only)
        </button>
      </main>
    );
  }

  return (
    <main className="container" id="main-content">
      <img 
        src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80" 
        alt="Scenic mountain landscape with a lake reflecting the peaks at sunset" 
        className="image-preview" 
      />
      <div className="image-info">
        <h1>Mountain Reflections</h1>
        <p>Captured in the High Sierras • Sept 2023</p>
        <button 
          ref={triggerRef}
          className="trigger" 
          onClick={handleDeleteClick}
          aria-haspopup="dialog"
        >
          Delete Image
        </button>
      </div>

      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onConfirm={handleConfirmDelete}
        title="Delete Image?"
        description="Are you sure you want to delete 'Mountain Reflections'? This action cannot be undone."
        triggerRef={triggerRef}
      />
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ImagePreviewPage />);
