  --text-muted: #64748b;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background-color: var(--bg);
  color: var(--text-main);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.container {
  max-width: 600px;
  width: 90%;
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  text-align: center;
}

.image-preview {
  width: 100%;
  height: 400px;
  object-fit: cover;
  border-radius: calc(var(--radius) - 4px);
  margin-bottom: 20px;
  background-color: #e2e8f0;
}

.image-info h1 {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.image-info p {
  color: var(--text-muted);
  margin-bottom: 24px;
}

button {
  cursor: pointer;
  font-family: inherit;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: 8px;
  border: none;
  transition: all 0.2s;
}

button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.trigger {
  background-color: var(--danger);
  color: white;
}

.trigger:hover {
  background-color: var(--danger-hover);
}

.trigger:focus-visible {
  outline: 2px solid var(--danger);
}

/* Modal Styles */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
  padding: 20px;
  backdrop-filter: blur(4px);
}

.modal-content {
  background: var(--card-bg);
  padding: 32px;
  border-radius: var(--radius);
  box-shadow: var(--shadow-lg);
  max-width: 400px;
  width: 100%;
  position: relative;
}

.modal-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.modal-description {
  color: var(--text-muted);
  margin-bottom: 24px;
}

.modal-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

.btn-secondary {
  background: #f1f5f9;
  color: var(--text-main);
}

.btn-secondary:hover {
  background: #e2e8f0;
}

.btn-danger {
  background: var(--danger);
  color: white;
}

.btn-danger:hover {
  background: var(--danger-hover);
}

/* Visually Hidden */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link:focus {
  position: absolute;
  top: 10px;
  left: 10px;
  width: auto;
  height: auto;
  background: white;
  padding: 10px;
  z-index: 2000;
  clip: auto;
  text-decoration: none;
  color: var(--primary);
  border: 2px solid var(--primary);
  border-radius: 4px;
}
